-- The vehicle lists a server starts with: the brands most sold in Brazil and their usual models, old and new, the same
-- as STARTING_VEHICLE_BRANDS in @apc/domain/vehicle-lists. A brand held under another name (VEHICLE_BRAND_ALIASES)
-- comes first: renamed to its standard name when that isn't held, or else merged into it the way the lists' merge
-- does it, its models moving to the standard brand (joining the one of the same name there) with its items' vehicles,
-- an item left with the same vehicle twice keeping it once; a brand of the catalog is never merged away. Then each
-- listed brand and model is added unless its list holds its name already, so the user's own entries and spellings
-- stay. No item is deleted, and running this on lists that hold everything changes nothing.

-- GM -> Chevrolet
UPDATE "Brand" SET "name" = 'Chevrolet', "nameKey" = 'chevrolet' WHERE "nameKey" = 'gm' AND NOT EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'chevrolet');
UPDATE "ItemVehicle" SET "vehicleModelId" = (SELECT t."id" FROM "VehicleModel" t JOIN "VehicleModel" m ON t."nameKey" = m."nameKey" WHERE m."id" = "ItemVehicle"."vehicleModelId" AND t."brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'chevrolet')) WHERE EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'gm') AND EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'chevrolet') AND NOT EXISTS (SELECT 1 FROM "CatalogBrand" WHERE "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm')) AND "vehicleModelId" IN (SELECT m."id" FROM "VehicleModel" m WHERE m."brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm') AND m."nameKey" IN (SELECT t."nameKey" FROM "VehicleModel" t WHERE t."brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'chevrolet')));
DELETE FROM "VehicleModel" WHERE EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'gm') AND EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'chevrolet') AND NOT EXISTS (SELECT 1 FROM "CatalogBrand" WHERE "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm')) AND "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm') AND "nameKey" IN (SELECT t."nameKey" FROM "VehicleModel" t WHERE t."brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'chevrolet'));
UPDATE "VehicleModel" SET "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'chevrolet') WHERE EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'gm') AND EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'chevrolet') AND NOT EXISTS (SELECT 1 FROM "CatalogBrand" WHERE "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm')) AND "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm');
UPDATE "ItemVehicle" SET "vehicleBrandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'chevrolet') WHERE EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'gm') AND EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'chevrolet') AND NOT EXISTS (SELECT 1 FROM "CatalogBrand" WHERE "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm')) AND "vehicleBrandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm');
DELETE FROM "ItemVehicle" WHERE "id" IN (SELECT r."id" FROM (SELECT "id", ROW_NUMBER() OVER (PARTITION BY "itemId", "vehicleModelId", "firstYear", "lastYear", LOWER(TRIM(COALESCE("version", ''))) ORDER BY "position", "id") AS n FROM "ItemVehicle" WHERE "vehicleBrandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'chevrolet')) r WHERE r.n > 1);
DELETE FROM "Brand" WHERE EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'gm') AND EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'chevrolet') AND NOT EXISTS (SELECT 1 FROM "CatalogBrand" WHERE "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm')) AND "id" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gm');

