DELETE FROM "ItemVehicle" WHERE "id" IN (SELECT r."id" FROM (SELECT "id", ROW_NUMBER() OVER (PARTITION BY "itemId", "vehicleModelId", "firstYear", "lastYear", LOWER(TRIM(COALESCE("version", ''))) ORDER BY "position", "id") AS n FROM "ItemVehicle" WHERE "vehicleBrandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'gwm')) r WHERE r.n > 1);
DELETE FROM "Brand" WHERE EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'haval') AND EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'gwm') AND NOT EXISTS (SELECT 1 FROM "CatalogBrand" WHERE "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'haval')) AND "id" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'haval');

-- RAM -> Dodge
UPDATE "Brand" SET "name" = 'Dodge', "nameKey" = 'dodge' WHERE "nameKey" = 'ram' AND NOT EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'dodge');
UPDATE "ItemVehicle" SET "vehicleModelId" = (SELECT t."id" FROM "VehicleModel" t JOIN "VehicleModel" m ON t."nameKey" = m."nameKey" WHERE m."id" = "ItemVehicle"."vehicleModelId" AND t."brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'dodge')) WHERE EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'ram') AND EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'dodge') AND NOT EXISTS (SELECT 1 FROM "CatalogBrand" WHERE "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'ram')) AND "vehicleModelId" IN (SELECT m."id" FROM "VehicleModel" m WHERE m."brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'ram') AND m."nameKey" IN (SELECT t."nameKey" FROM "VehicleModel" t WHERE t."brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'dodge')));
DELETE FROM "VehicleModel" WHERE EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'ram') AND EXISTS (SELECT 1 FROM "Brand" WHERE "nameKey" = 'dodge') AND NOT EXISTS (SELECT 1 FROM "CatalogBrand" WHERE "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'ram')) AND "brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'ram') AND "nameKey" IN (SELECT t."nameKey" FROM "VehicleModel" t WHERE t."brandId" = (SELECT "id" FROM "Brand" WHERE "nameKey" = 'dodge'));
